var y = Math.max(0, +v('year') || 0), years = Math.max(1, +v('years') || 1);
var total = Math.round(y * years);
if (total < 1) { if (el._crowdStop) el._crowdStop(); el.innerHTML = ''; return; }
Crowd.units(el, { total: total, used: 0, unit: '回', leftLabel: 'これから',
title: 'これから行けるライブを玉で並べると',
final: function (l) { return 'これから行けるのは約 ' + l.toLocaleString('ja-JP') + '回。次のライブも、この中の大切な1回です。'; } });
